with not_flagged as (select s.* from orders s where exists (select 1 from order_items x where x.order_id = s.id and x.quantity is not null)), with_windows as (select id, channel, lag(shipping_fee) over w_running prev_shipping_fee, lead(shipping_fee) over w_running next_shipping_fee, lag(discount) over w_running prev_discount, row_number() over w_running seq_no from not_flagged window w_running as (partition by customer_id order by shipping_fee, id)), latest as (select id, prev_shipping_fee, prev_discount from (select *, row_number() over (partition by channel order by seq_no, id) as dedup_rank from with_windows) x where dedup_rank = 1), matched_keys as (select id from latest except select id from orders where amount is null), reconciled as (select s.* from latest s inner join matched_keys k on s.id = k.id), metrics as (select id, prev_shipping_fee, prev_discount, rank() over (order by prev_shipping_fee desc nulls last) prev_shipping_fee_rank, dense_rank() over (order by prev_discount) prev_discount_dense_rank, rank() over (order by prev_discount) prev_discount_rank from reconciled) select case when prev_shipping_fee_rank >= 8 then 'HIGH' else 'LOW' end as prev_shipping_fee_rank_tier, round(avg(prev_discount_dense_rank), 2) as avg_prev_discount_dense_rank, approx_percentile(prev_discount, array(0.25, 0.5, 0.75)) as prev_discount_quartiles, count(distinct id) as distinct_ids from metrics group by case when prev_shipping_fee_rank >= 8 then 'HIGH' else 'LOW' end having round(avg(prev_discount_dense_rank), 2) > 0 order by distinct_ids
